 *
 * Mirrors the compiler-synthesized kotlin.reflect.KSuspendFunctionN hierarchy:
 * on the JVM these interfaces are generated by the compiler next to suspend
 * function types and have no standalone runtime class. Declaring them here
 * gives imports and the inherited function/reflection supertypes the same
 * source-backed shape that KFunction.kt gives KFunctionN.
 */

package kotlin.reflect

// A suspend callable reference is both a KFunction<R> and the matching suspend
// function type, so each arity declares both supertypes. `is KSuspendFunctionN`
// erases to the KFunction classifier at runtime (these synthesized interfaces
// have no distinct runtime class), while invocation resolves through the
// SuspendFunctionN supertype.
public interface KSuspendFunction0<out R> : KFunction<R>, suspend () -> R
public interface KSuspendFunction1<in P1, out R> : KFunction<R>, suspend (P1) -> R
public interface KSuspendFunction2<in P1, in P2, out R> : KFunction<R>, suspend (P1, P2) -> R
public interface KSuspendFunction3<in P1, in P2, in P3, out R> : KFunction<R>, suspend (P1, P2, P3) -> R
public interface KSuspendFunction4<in P1, in P2, in P3, in P4, out R> : KFunction<R>, suspend (P1, P2, P3, P4) -> R
public interface KSuspendFunction5<in P1, in P2, in P3, in P4, in P5, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5) -> R
public interface KSuspendFunction6<in P1, in P2, in P3, in P4, in P5, in P6, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6) -> R
public interface KSuspendFunction7<in P1, in P2, in P3, in P4, in P5, in P6, in P7, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6, P7) -> R
public interface KSuspendFunction8<in P1, in P2, in P3, in P4, in P5, in P6, in P7, in P8, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6, P7, P8) -> R
public interface KSuspendFunction9<in P1, in P2, in P3, in P4, in P5, in P6, in P7, in P8, in P9, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6, P7, P8, P9) -> R
public interface KSuspendFunction10<in P1, in P2, in P3, in P4, in P5, in P6, in P7, in P8, in P9, in P10, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6, P7, P8, P9, P10) -> R
public interface KSuspendFunction11<in P1, in P2, in P3, in P4, in P5, in P6, in P7, in P8, in P9, in P10, in P11, out R> : KFunction<R>, suspend (P1, P2, P3, P4, P5, P6, P7, P8, P9, P10, P11) -> R
